public static TestSparkRunner fromOptions(PipelineOptions options) {
  try {
    TestSparkPipelineOptions sparkOptions = PipelineOptionsValidator.validate(TestSparkPipelineOptions.class, options);
    return new TestSparkRunner(sparkOptions);
  } catch (IllegalArgumentException e) {
    // Handle the validation error, possibly by logging and providing a user-friendly message
    System.err.println("Validation error: " + e.getMessage());
    return null;
  } catch (RuntimeException e) {
    // Log the critical error and stop the application or fix the problem
    e.printStackTrace();
    throw e;
  }
}
